import pytest
import os
from unittest.mock import patch, MagicMock
from demisto_sdk.dev_tools.lint_manager import LintManager

def mock_get_dev_requirements(*args, **kwargs):
    return ""

@patch('demisto_sdk.dev_tools.lint_manager.get_dev_requirements', side_effect=mock_get_dev_requirements)
def test_no_changes_with_git_flag(mock_dev_req):
    """After fix, with git flag and no changes, package should be skipped."""
    def mock_run_command(cmd):
        if 'rev-parse' in cmd:
            return 'feature'
        elif 'origin/master...feature' in cmd:
            return ''
        elif '--name-only' in cmd:
            return ''
        else:
            raise ValueError(f"Unexpected command: {cmd}")
    with patch('demisto_sdk.dev_tools.lint_manager.run_command', side_effect=mock_run_command):
        manager = LintManager('Packs/Pack1', git=True)
        result = manager._check_should_run_pkg('Packs/Pack1')
        assert result is False, "Should return False when no changes"

@patch('demisto_sdk.dev_tools.lint_manager.get_dev_requirements', side_effect=mock_get_dev_requirements)
def test_changes_with_git_flag(mock_dev_req):
    """After fix, with git flag and changes, package should be selected."""
    def mock_run_command(cmd):
        if 'rev-parse' in cmd:
            return 'feature'
        elif 'origin/master...feature' in cmd:
            return 'diff --git a/Packs/Pack1/Integrations/Int1/Int1.py ...'
        elif '--name-only' in cmd:
            return ''
        else:
            raise ValueError(f"Unexpected command: {cmd}")
    with patch('demisto_sdk.dev_tools.lint_manager.run_command', side_effect=mock_run_command):
        manager = LintManager('Packs/Pack1', git=True)
        result = manager._check_should_run_pkg('Packs/Pack1')
        assert result is True, "Should return True when there are changes"

@patch('demisto_sdk.dev_tools.lint_manager.get_dev_requirements', side_effect=mock_get_dev_requirements)
def test_without_git_flag_runs_all(mock_dev_req):
    """Without git flag, all provided packages are selected."""
    manager = LintManager('Packs/Pack1,Packs/Pack2', git=False)
    assert 'Packs/Pack1' in manager.pkgs
    assert 'Packs/Pack2' in manager.pkgs
    assert len(manager.pkgs) == 2

if __name__ == "__main__":
    import sys
    sys.exit(pytest.main(["-v", __file__]))

