import pytest
import subprocess
import tempfile
import os
import sys

def compile_and_run(cpp_source, extra_includes=None):
    """Compile a C++ program with flatbuffers and run it."""
    with tempfile.NamedTemporaryFile(mode='w', suffix='.cpp', delete=False) as f:
        f.write(cpp_source)
        cpp_file = f.name
    try:
        # Compile with g++
        include_path = '/workspace/flatbuffers/include'
        test_include_path = '/workspace/flatbuffers/tests'
        exe_file = cpp_file + '.exe'
        cmd = ['g++', '-std=c++11', '-I', include_path, '-I', test_include_path,
               '-o', exe_file, cpp_file]
        result = subprocess.run(cmd, capture_output=True, text=True)
        if result.returncode != 0:
            raise RuntimeError(f"Compilation failed: {result.stderr}")
        # Run the executable
        run_result = subprocess.run([exe_file], capture_output=True, text=True)
        return run_result.returncode, run_result.stdout, run_result.stderr
    finally:
        os.unlink(cpp_file)
        if os.path.exists(exe_file):
            os.unlink(exe_file)

def test_new_filler_overload():
    """Test that the new CreateVectorOfStructs with filler works."""
    source = '''
#include "flatbuffers/flatbuffers.h"
#include "monster_test_generated.h"
#include <iostream>
#include <cassert>

using namespace MyGame::Example;

int main() {
    flatbuffers::FlatBufferBuilder builder;
    const size_t count = 100;
    auto offset = builder.CreateVectorOfStructs<Test>(
        count,
        [](size_t i, Test* t) {
            t->mutate_a(static_cast<int16_t>(i));
            t->mutate_b(static_cast<int8_t>(i % 128));
        }
    );
    builder.Finish(offset);
    auto buffer = builder.GetBufferPointer();
    auto size = builder.GetSize();
    // Verify by reading back
    auto vec = flatbuffers::GetRoot<flatbuffers::Vector<const Test*>>(buffer);
    assert(vec->size() == count);
    for (size_t i = 0; i < count; ++i) {
        auto t = vec->Get(i);
        assert(t->a() == static_cast<int16_t>(i));
        assert(t->b() == static_cast<int8_t>(i % 128));
    }
    std::cout << "PASS" << std::endl;
    return 0;
}
'''
    returncode, stdout, stderr = compile_and_run(source)
    assert returncode == 0, f"Program failed with stderr: {stderr}"
    assert "PASS" in stdout

def test_old_method_still_works():
    """Test that the old CreateVectorOfStructs with temporary array still works."""
    source = '''
#include "flatbuffers/flatbuffers.h"
#include "monster_test_generated.h"
#include <iostream>
#include <cassert>
#include <vector>

using namespace MyGame::Example;

int main() {
    flatbuffers::FlatBufferBuilder builder;
    const size_t count = 50;
    std::vector<Test> temp;
    temp.reserve(count);
    for (size_t i = 0; i < count; ++i) {
        temp.push_back(Test(static_cast<int16_t>(i), static_cast<int8_t>(i % 128)));
    }
    auto offset = builder.CreateVectorOfStructs(temp);
    builder.Finish(offset);
    auto buffer = builder.GetBufferPointer();
    auto size = builder.GetSize();
    auto vec = flatbuffers::GetRoot<flatbuffers::Vector<const Test*>>(buffer);
    assert(vec->size() == count);
    for (size_t i = 0; i < count; ++i) {
        auto t = vec->Get(i);
        assert(t->a() == static_cast<int16_t>(i));
        assert(t->b() == static_cast<int8_t>(i % 128));
    }
    std::cout << "PASS" << std::endl;
    return 0;
}
'''
    returncode, stdout, stderr = compile_and_run(source)
    assert returncode == 0, f"Program failed with stderr: {stderr}"
    assert "PASS" in stdout

def test_empty_vector():
    """Test that creating an empty vector with filler works (should not crash)."""
    source = '''
#include "flatbuffers/flatbuffers.h"
#include "monster_test_generated.h"
#include <iostream>
#include <cassert>

using namespace MyGame::Example;

int main() {
    flatbuffers::FlatBufferBuilder builder;
    auto offset = builder.CreateVectorOfStructs<Test>(
        0,
        [](size_t i, Test* t) {
            // Should never be called
            assert(false);
        }
    );
    builder.Finish(offset);
    auto buffer = builder.GetBufferPointer();
    auto vec = flatbuffers::GetRoot<flatbuffers::Vector<const Test*>>(buffer);
    assert(vec->size() == 0);
    std::cout << "PASS" << std::endl;
    return 0;
}
'''
    returncode, stdout, stderr = compile_and_run(source)
    assert returncode == 0, f"Program failed with stderr: {stderr}"
    assert "PASS" in stdout

if __name__ == "__main__":
    sys.exit(pytest.main(["-v", __file__]))

